  "settings.backup_title": "Sauvegarde et Restauration de la configuration",
  "settings.backup_desc": "Une sauvegarde des réglages contient les personnes et les mots de passe, les partages, les réglages des applications, les clés cloud et l’apparence du bureau. Elle est toujours chiffrée avec une phrase secrète que vous choisissez. Une sauvegarde envoyée est vérifiée et gardée prête ; elle s’applique au prochain redémarrage de Kiboto.",
